import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

bn_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor bn2d_forward(torch::Tensor x,
                           c10::optional<torch::Tensor> gamma,
                           c10::optional<torch::Tensor> beta,
                           c10::optional<torch::Tensor> running_mean,
                           c10::optional<torch::Tensor> running_var,
                           double momentum, double eps, bool training);
"""

bn_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Fused BatchNorm2d forward (NCHW, float32), restructured into 3 kernels:
//  1) bn2d_reduce_kernel:    multi-block-per-channel partial sum/sumsq
//                             reductions combined via double-precision atomics
//  2) bn2d_finalize_kernel:  per-channel mean/invstd + running-stat update
//  3) bn2d_normalize_kernel: fully parallel, vectorized normalize+affine pass
// The original design used ONE thread-block per channel, so with small C the
// GPU was severely underutilized. Splitting the per-channel reduction across
// many blocks (over the batch dim) and making the normalize pass fully
// parallel keeps the device saturated regardless of C.
template <int Threads>
__global__ void bn2d_reduce_kernel(const float* __restrict__ X,
                                   double* __restrict__ red,  // [2*C], zero-initialized
                                   int N, int C, int HW)
{
  const int c   = blockIdx.x;
  const int tid = threadIdx.x;
  const int S   = gridDim.y;
  constexpr int NW = Threads / 32;
  __shared__ double s_red[2 * NW];
  // CuTe global tensors for this channel (shape (N, HW), stride (C*HW, 1))
  Tensor mX = make_tensor(make_gmem_ptr(X + (int64_t)c * HW),
                          make_shape(N, HW),
                          make_stride((int64_t)C * HW, Int<1>{}));
  // Vectorized (float4) view, valid when HW % 4 == 0
  Tensor mX4 = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(X + (int64_t)c * HW)),
                           make_shape(N, HW / 4),
                           make_stride((int64_t)C * (HW / 4), Int<1>{}));
  // ---- Partial reduction over a strided subset of the batch ----
  // Unrolled by 4 float4 vectors per iteration with two independent
  // accumulator pairs. This exposes much more memory-level parallelism
  // (multiple outstanding 16B loads per thread) and breaks the serial
  // FP64 accumulation dependency chain, raising the effective DRAM
  // throughput of this bandwidth-bound pass.
  double sum0 = 0.0, sumsq0 = 0.0;
  double sum1 = 0.0, sumsq1 = 0.0;
  if ((HW & 3) == 0) {
    const int HW4 = HW >> 2;
    for (int n = blockIdx.y; n < N; n += S) {
      int i = tid;
      for (; i + 3 * Threads < HW4; i += 4 * Threads) {
        float4 v0 = __ldcs(&mX4(n, i));
        float4 v1 = __ldcs(&mX4(n, i + Threads));
        float4 v2 = __ldcs(&mX4(n, i + 2 * Threads));
        float4 v3 = __ldcs(&mX4(n, i + 3 * Threads));
        // Pre-reduce the 4 lanes of each float4 in single precision and
        // promote to double only once per vector, as before.
        const float vs0 = (v0.x + v0.y) + (v0.z + v0.w);
        const float vs1 = (v1.x + v1.y) + (v1.z + v1.w);
        const float vs2 = (v2.x + v2.y) + (v2.z + v2.w);
        const float vs3 = (v3.x + v3.y) + (v3.z + v3.w);
        const float vq0 = fmaf(v0.x, v0.x, fmaf(v0.y, v0.y, fmaf(v0.z, v0.z, v0.w * v0.w)));
        const float vq1 = fmaf(v1.x, v1.x, fmaf(v1.y, v1.y, fmaf(v1.z, v1.z, v1.w * v1.w)));
        const float vq2 = fmaf(v2.x, v2.x, fmaf(v2.y, v2.y, fmaf(v2.z, v2.z, v2.w * v2.w)));
        const float vq3 = fmaf(v3.x, v3.x, fmaf(v3.y, v3.y, fmaf(v3.z, v3.z, v3.w * v3.w)));
        sum0   += (double)vs0 + (double)vs1;
        sumsq0 += (double)vq0 + (double)vq1;
        sum1   += (double)vs2 + (double)vs3;
        sumsq1 += (double)vq2 + (double)vq3;
      }
      for (; i < HW4; i += Threads) {
        float4 v = __ldcs(&mX4(n, i));
        const float vs = (v.x + v.y) + (v.z + v.w);
        const float vq = fmaf(v.x, v.x, fmaf(v.y, v.y, fmaf(v.z, v.z, v.w * v.w)));
        sum0   += (double)vs;
        sumsq0 += (double)vq;
      }
    }
  } else {
    for (int n = blockIdx.y; n < N; n += S) {
      for (int i = tid; i < HW; i += Threads) {
        float v = __ldcs(&mX(n, i));
        sum0   += (double)v;
        sumsq0 += (double)v * v;
      }
    }
  }
  double sum = sum0 + sum1, sumsq = sumsq0 + sumsq1;
  // Warp-level reduction
  #pragma unroll
  for (int off = 16; off > 0; off >>= 1) {
    sum   += __shfl_down_sync(0xffffffffu, sum, off);
    sumsq += __shfl_down_sync(0xffffffffu, sumsq, off);
  }
  const int lane = tid & 31;
  const int warp = tid >> 5;
  if (lane == 0) {
    s_red[warp]      = sum;
    s_red[NW + warp] = sumsq;
  }
  __syncthreads();
  if (warp == 0) {
    sum   = (lane < NW) ? s_red[lane]      : 0.0;
    sumsq = (lane < NW) ? s_red[NW + lane] : 0.0;
    #pragma unroll
    for (int off = NW / 2; off > 0; off >>= 1) {
      sum   += __shfl_down_sync(0xffffffffu, sum, off);
      sumsq += __shfl_down_sync(0xffffffffu, sumsq, off);
    }
    if (lane == 0) {
      // Combine partials across the S blocks of this channel
      atomicAdd(&red[c],     sum);
      atomicAdd(&red[C + c], sumsq);
    }
  }
}
// One thread per channel: finalize statistics and update running stats.
__global__ void bn2d_finalize_kernel(const double* __restrict__ red,
                                     float* __restrict__ stats,  // [2*C]: mean, invstd
                                     float* __restrict__ RM,
                                     float* __restrict__ RV,
                                     int C, int64_t total,
                                     float eps, float momentum)
{
  const int c = blockIdx.x * blockDim.x + threadIdx.x;
  if (c >= C) return;
  const double sum   = red[c];
  const double sumsq = red[C + c];
  const double mean  = sum / (double)total;
  double var = sumsq / (double)total - mean * mean;  // biased var (used for normalize)
  if (var < 0.0) var = 0.0;
  stats[c]     = (float)mean;
  stats[C + c] = rsqrtf((float)var + eps);
  if (RM != nullptr) {
    RM[c] = (1.f - momentum) * RM[c] + momentum * (float)mean;
  }
  if (RV != nullptr) {
    // running_var updated with unbiased variance (matches PyTorch)
    const double unb = (total > 1) ? var * (double)total / (double)(total - 1) : var;
    RV[c] = (1.f - momentum) * RV[c] + momentum * (float)unb;
  }
}
// Fully parallel normalize + affine pass (vectorized when HW % 4 == 0).
// Each thread block owns exactly one (n, c) plane, so the data it touches
// is fully contiguous in memory and the hot loop needs no per-iteration
// 64-bit index division (the previous version recomputed idx/HW4 every
// iteration). Threads simply stride over the plane with float4 accesses.
template <int Threads>
__global__ void bn2d_normalize_kernel(const float* __restrict__ X,
                                      float* __restrict__ Y,
                                      const float* __restrict__ G,
                                      const float* __restrict__ B,
                                      const float* __restrict__ stats,  // [2*C] mean/invstd (training)
                                      const float* __restrict__ RM,     // running stats (eval)
                                      const float* __restrict__ RV,
                                      int N, int C, int HW,
                                      float eps, int training)
{
  const int c   = (int)(blockIdx.x / (unsigned)N);
  const int n   = (int)(blockIdx.x - (unsigned)c * (unsigned)N);
  const int tid = threadIdx.x;
  float mean, invstd;
  if (training) {
    mean   = stats[c];
    invstd = stats[C + c];
  } else {
    mean   = RM[c];
    invstd = rsqrtf(RV[c] + eps);
  }
  const float g     = (G != nullptr) ? G[c] : 1.0f;
  const float b     = (B != nullptr) ? B[c] : 0.0f;
  const float scale = invstd * g;
  const float shift = b - mean * scale;
  // The (n, c) plane is contiguous: X + (n*C + c)*HW .. +HW
  const float* xbase = X + ((int64_t)n * C + c) * HW;
  float*       ybase = Y + ((int64_t)n * C + c) * HW;
  if ((HW & 3) == 0) {
    const int HW4 = HW >> 2;
    Tensor mX4 = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(xbase)),
                             make_shape(HW4),
                             make_stride(Int<1>{}));
    Tensor mY4 = make_tensor(make_gmem_ptr(reinterpret_cast<float4*>(ybase)),
                             make_shape(HW4),
                             make_stride(Int<1>{}));
    int i = tid;
    // Unrolled by 4 float4 vectors per iteration: each thread keeps
    // multiple independent 16B loads/stores in flight, increasing
    // memory-level parallelism on this bandwidth-bound streaming pass.
    for (; i + 3 * Threads < HW4; i += 4 * Threads) {
      float4 v0 = __ldcs(&mX4(i));
      float4 v1 = __ldcs(&mX4(i + Threads));
      float4 v2 = __ldcs(&mX4(i + 2 * Threads));
      float4 v3 = __ldcs(&mX4(i + 3 * Threads));
      float4 o0, o1, o2, o3;
      o0.x = fmaf(v0.x, scale, shift);
      o0.y = fmaf(v0.y, scale, shift);
      o0.z = fmaf(v0.z, scale, shift);
      o0.w = fmaf(v0.w, scale, shift);
      o1.x = fmaf(v1.x, scale, shift);
      o1.y = fmaf(v1.y, scale, shift);
      o1.z = fmaf(v1.z, scale, shift);
      o1.w = fmaf(v1.w, scale, shift);
      o2.x = fmaf(v2.x, scale, shift);
      o2.y = fmaf(v2.y, scale, shift);
      o2.z = fmaf(v2.z, scale, shift);
      o2.w = fmaf(v2.w, scale, shift);
      o3.x = fmaf(v3.x, scale, shift);
      o3.y = fmaf(v3.y, scale, shift);
      o3.z = fmaf(v3.z, scale, shift);
      o3.w = fmaf(v3.w, scale, shift);
      __stcs(&mY4(i), o0);
      __stcs(&mY4(i + Threads), o1);
      __stcs(&mY4(i + 2 * Threads), o2);
      __stcs(&mY4(i + 3 * Threads), o3);
    }
    for (; i < HW4; i += Threads) {
      float4 v = __ldcs(&mX4(i));
      float4 o;
      o.x = fmaf(v.x, scale, shift);
      o.y = fmaf(v.y, scale, shift);
      o.z = fmaf(v.z, scale, shift);
      o.w = fmaf(v.w, scale, shift);
      __stcs(&mY4(i), o);
    }
  } else {
    Tensor mX = make_tensor(make_gmem_ptr(xbase),
                            make_shape(HW),
                            make_stride(Int<1>{}));
    Tensor mY = make_tensor(make_gmem_ptr(ybase),
                            make_shape(HW),
                            make_stride(Int<1>{}));
    for (int i = tid; i < HW; i += Threads) {
      __stcs(&mY(i), fmaf(__ldcs(&mX(i)), scale, shift));
    }
  }
}
torch::Tensor bn2d_forward(torch::Tensor x,
                           c10::optional<torch::Tensor> gamma,
                           c10::optional<torch::Tensor> beta,
                           c10::optional<torch::Tensor> running_mean,
                           c10::optional<torch::Tensor> running_var,
                           double momentum, double eps, bool training)
{
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be NCHW (4D)");
  auto x_c = x.contiguous();
  const int64_t N  = x_c.size(0);
  const int64_t C  = x_c.size(1);
  const int64_t H  = x_c.size(2);
  const int64_t W  = x_c.size(3);
  const int64_t HW = H * W;
  TORCH_CHECK(C > 0 && HW > 0, "invalid input shape");
  auto y = torch::empty_like(x_c);
  const float* g_ptr = nullptr;
  const float* b_ptr = nullptr;
  torch::Tensor g_c, b_c;
  if (gamma.has_value()) {
    g_c = gamma.value().contiguous();
    TORCH_CHECK(g_c.is_cuda() && g_c.scalar_type() == at::kFloat && g_c.numel() == C,
                "gamma must be CUDA float32 of size C");
    g_ptr = g_c.data_ptr<float>();
  }
  if (beta.has_value()) {
    b_c = beta.value().contiguous();
    TORCH_CHECK(b_c.is_cuda() && b_c.scalar_type() == at::kFloat && b_c.numel() == C,
                "beta must be CUDA float32 of size C");
    b_ptr = b_c.data_ptr<float>();
  }
  float* rm_ptr = nullptr;
  float* rv_ptr = nullptr;
  torch::Tensor rm_c, rv_c;
  if (running_mean.has_value()) {
    rm_c = running_mean.value().contiguous();
    TORCH_CHECK(rm_c.is_cuda() && rm_c.scalar_type() == at::kFloat && rm_c.numel() == C,
                "running_mean must be CUDA float32 of size C");
    rm_ptr = rm_c.data_ptr<float>();
  }
  if (running_var.has_value()) {
    rv_c = running_var.value().contiguous();
    TORCH_CHECK(rv_c.is_cuda() && rv_c.scalar_type() == at::kFloat && rv_c.numel() == C,
                "running_var must be CUDA float32 of size C");
    rv_ptr = rv_c.data_ptr<float>();
  }
  if (!training) {
    TORCH_CHECK(rm_ptr != nullptr && rv_ptr != nullptr,
                "running stats required in eval mode");
  }
  constexpr int Threads = 256;
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  // One thread block per (n, c) plane for the normalize pass
  const unsigned nblocks = (unsigned)(N * C);
  if (training) {
    // Scratch: [0, C) sums, [C, 2C) sum-of-squares (double), plus mean/invstd
    auto red   = torch::zeros({2 * C}, x_c.options().dtype(at::kDouble));
    auto stats = torch::empty({2 * C}, x_c.options());
    // Split each channel's reduction across S blocks (over the batch dim)
    int S = 1;
    while (S < 32 && (int64_t)C * S < 2048 && (int64_t)S < N) S <<= 1;
    bn2d_reduce_kernel<Threads><<<dim3((unsigned)C, (unsigned)S), dim3(Threads), 0, stream>>>(
        x_c.data_ptr<float>(),
        red.data_ptr<double>(),
        (int)N, (int)C, (int)HW);
    const int fblocks = (int)((C + 127) / 128);
    bn2d_finalize_kernel<<<dim3(fblocks), dim3(128), 0, stream>>>(
        red.data_ptr<double>(),
        stats.data_ptr<float>(),
        rm_ptr, rv_ptr,
        (int)C, N * HW,
        (float)eps, (float)momentum);
    bn2d_normalize_kernel<Threads><<<dim3(nblocks), dim3(Threads), 0, stream>>>(
        x_c.data_ptr<float>(),
        y.data_ptr<float>(),
        g_ptr, b_ptr,
        stats.data_ptr<float>(),
        rm_ptr, rv_ptr,
        (int)N, (int)C, (int)HW,
        (float)eps, 1);
  } else {
    bn2d_normalize_kernel<Threads><<<dim3(nblocks), dim3(Threads), 0, stream>>>(
        x_c.data_ptr<float>(),
        y.data_ptr<float>(),
        g_ptr, b_ptr,
        nullptr,
        rm_ptr, rv_ptr,
        (int)N, (int)C, (int)HW,
        (float)eps, 0);
  }
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "bn2d kernels launch failed: ",
              cudaGetErrorString(err));
  return y;
}
"""

bn_ext = load_inline(
    name="cute_bn2d_ext",
    cpp_sources=bn_cpp_decl,
    cuda_sources=bn_cuda_src,
    functions=["bn2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class _BatchNorm2dCute(nn.Module):
    """
    BatchNorm2d-compatible module backed by a single fused CuTe/CUDA kernel.
    Mirrors nn.BatchNorm2d parameter/buffer names so state_dicts are compatible.
    """

    def __init__(self, num_features: int, eps: float = 1e-5, momentum: float = 0.1):
        super().__init__()
        self.num_features = int(num_features)
        self.eps = float(eps)
        self.momentum = float(momentum)

        self.weight = nn.Parameter(torch.ones(self.num_features))
        self.bias = nn.Parameter(torch.zeros(self.num_features))
        self.register_buffer("running_mean", torch.zeros(self.num_features))
        self.register_buffer("running_var", torch.ones(self.num_features))
        self.register_buffer("num_batches_tracked", torch.tensor(0, dtype=torch.long))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        y = bn_ext.bn2d_forward(
            x,
            self.weight,
            self.bias,
            self.running_mean,
            self.running_var,
            self.momentum,
            self.eps,
            self.training,
        )
        if self.training:
            self.num_batches_tracked += 1
        return y


class ModelNew(nn.Module):
    """
    Simple model that performs Batch Normalization using a custom CuTe kernel.
    """

    def __init__(self, num_features: int):
        super(ModelNew, self).__init__()
        self.bn = _BatchNorm2dCute(num_features=num_features)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.bn(x)

