bn_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Fused BatchNorm2d forward (NCHW, float32), restructured into 3 kernels:
//  1) bn2d_reduce_kernel:    multi-block-per-channel partial sum/sumsq
//                             reductions combined via double-precision atomics
//  2) bn2d_finalize_kernel:  per-channel mean/invstd + running-stat update
//  3) bn2d_normalize_kernel: fully parallel, vectorized normalize+affine pass
// The original design used ONE thread-block per channel, so with small C the
// GPU was severely underutilized. Splitting the per-channel reduction across
// many blocks (over the batch dim) and making the normalize pass fully
// parallel keeps the device saturated regardless of C.
template <int Threads>
__global__ void bn2d_reduce_kernel(const float* __restrict__ X,
                                   double* __restrict__ red,  // [2*C], zero-initialized
                                   int N, int C, int HW)
{
  const int c   = blockIdx.x;
  const int tid = threadIdx.x;
  const int S   = gridDim.y;
  constexpr int NW = Threads / 32;
  __shared__ double s_red[2 * NW];
  // CuTe global tensors for this channel (shape (N, HW), stride (C*HW, 1))
  Tensor mX = make_tensor(make_gmem_ptr(X + (int64_t)c * HW),
                          make_shape(N, HW),
                          make_stride((int64_t)C * HW, Int<1>{}));
  // Vectorized (float4) view, valid when HW % 4 == 0
  Tensor mX4 = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(X + (int64_t)c * HW)),
                           make_shape(N, HW / 4),
                           make_stride((int64_t)C * (HW / 4), Int<1>{}));
  // ---- Partial reduction over a strided subset of the batch ----
  double sum = 0.0, sumsq = 0.0;
  if ((HW & 3) == 0) {
    const int HW4 = HW >> 2;
    for (int n = blockIdx.y; n < N; n += S) {
      for (int i = tid; i < HW4; i += Threads) {
        float4 v = __ldcs(&mX4(n, i));
        // Pre-reduce the 4 lanes of each float4 in single precision and
        // promote to double only once per vector. This cuts FP64 adds/FMAs
        // and F32->F64 conversions per element by ~4x, which is the real

        const float vs = (v.x + v.y) + (v.z + v.w);
        const float vq = fmaf(v.x, v.x, fmaf(v.y, v.y, fmaf(v.z, v.z, v.w * v.w)));
        sum   += (double)vs;
        sumsq += (double)vq;
      }
    }
  } else {
    for (int n = blockIdx.y; n < N; n += S) {
      for (int i = tid; i < HW; i += Threads) {
        float v = __ldcs(&mX(n, i));
        sum   += (double)v;
        sumsq += (double)v * v;
      }
    }
  }
  // Warp-level reduction
  #pragma unroll
  for (int off = 16; off > 0; off >>= 1) {
    sum   += __shfl_down_sync(0xffffffffu, sum, off);
    sumsq += __shfl_down_sync(0xffffffffu, sumsq, off);
  }
  const int lane = tid & 31;
  const int warp = tid >> 5;
  if (lane == 0) {
    s_red[warp]      = sum;
    s_red[NW + warp] = sumsq;
  }
  __syncthreads();
  if (warp == 0) {
    sum   = (lane < NW) ? s_red[lane]      : 0.0;
    sumsq = (lane < NW) ? s_red[NW + lane] : 0.0;
    #pragma unroll
    for (int off = NW / 2; off > 0; off >>= 1) {
      sum   += __shfl_down_sync(0xffffffffu, sum, off);
      sumsq += __shfl_down_sync(0xffffffffu, sumsq, off);
    }
    if (lane == 0) {
      // Combine partials across the S blocks of this channel
      atomicAdd(&red[c],     sum);
      atomicAdd(&red[C + c], sumsq);
    }
  }
}
// One thread per channel: finalize statistics and update running stats.
__global__ void bn2d_finalize_kernel(const double* __restrict__ red,
                                     float* __restrict__ stats,  // [2*C]: mean, invstd
                                     float* __restrict__ RM,
                                     float* __restrict__ RV,
                                     int C, int64_t total,
                                     float eps, float momentum)
{
  const int c = blockIdx.x * blockDim.x + threadIdx.x;
  if (c >= C) return;
  const double sum   = red[c];
  const double sumsq = red[C + c];
  const double mean  = sum / (double)total;
  double var = sumsq / (double)total - mean * mean;  // biased var (used for normalize)
  if (var < 0.0) var = 0.0;
  stats[c]     = (float)mean;
  stats[C + c] = rsqrtf((float)var + eps);
  if (RM != nullptr) {
    RM[c] = (1.f - momentum) * RM[c] + momentum * (float)mean;
  }
  if (RV != nullptr) {
    // running_var updated with unbiased variance (matches PyTorch)
    const double unb = (total > 1) ? var * (double)total / (double)(total - 1) : var;
    RV[c] = (1.f - momentum) * RV[c] + momentum * (float)unb;
  }
}
// Fully parallel normalize + affine pass (vectorized when HW % 4 == 0).
// Each thread block owns exactly one (n, c) plane, so the data it touches
// is fully contiguous in memory and the hot loop needs no per-iteration
// 64-bit index division (the previous version recomputed idx/HW4 every
// iteration). Threads simply stride over the plane with float4 accesses.
template <int Threads>
__global__ void bn2d_normalize_kernel(const float* __restrict__ X,
                                      float* __restrict__ Y,
                                      const float* __restrict__ G,
                                      const float* __restrict__ B,
                                      const float* __restrict__ stats,  // [2*C] mean/invstd (training)
                                      const float* __restrict__ RM,     // running stats (eval)
                                      const float* __restrict__ RV,
                                      int N, int C, int HW,
                                      float eps, int training)
{
  const int c   = (int)(blockIdx.x / (unsigned)N);
  const int n   = (int)(blockIdx.x - (unsigned)c * (unsigned)N);
  const int tid = threadIdx.x;
  float mean, invstd;
  if (training) {
    mean   = stats[c];
    invstd = stats[C + c];
  } else {
    mean   = RM[c];
    invstd = rsqrtf(RV[c] + eps);
  }
  const float g     = (G != nullptr) ? G[c] : 1.0f;
  const float b     = (B != nullptr) ? B[c] : 0.0f;
  const float scale = invstd * g;
  const float shift = b - mean * scale;
  // The (n, c) plane is contiguous: X + (n*C + c)*HW .. +HW
  const float* xbase = X + ((int64_t)n * C + c) * HW;
  float*       ybase = Y + ((int64_t)n * C + c) * HW;
  if ((HW & 3) == 0) {
    const int HW4 = HW >> 2;
    Tensor mX4 = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(xbase)),
                             make_shape(HW4),
                             make_stride(Int<1>{}));
    Tensor mY4 = make_tensor(make_gmem_ptr(reinterpret_cast<float4*>(ybase)),
                             make_shape(HW4),
                             make_stride(Int<1>{}));
    for (int i = tid; i < HW4; i += Threads) {
      float4 v = __ldcs(&mX4(i));
      float4 o;
      o.x = fmaf(v.x, scale, shift);
      o.y = fmaf(v.y, scale, shift);
      o.z = fmaf(v.z, scale, shift);
      o.w = fmaf(v.w, scale, shift);
      __stcs(&mY4(i), o);
    }
  } else {
    Tensor mX = make_tensor(make_gmem_ptr(xbase),
                            make_shape(HW),
                            make_stride(Int<1>{}));
    Tensor mY = make_tensor(make_gmem_ptr(ybase),
                            make_shape(HW),
                            make_stride(Int<1>{}));
    for (int i = tid; i < HW; i += Threads) {
      __stcs(&mY(i), fmaf(__ldcs(&mX(i)), scale, shift));
    }
  }
}
